from PIL import Image
import numpy as np
from collections import deque

a = np.asarray(Image.open('/app/dog_full.png').convert('L')).astype(np.float32)
dark = (a < 70)
h, w = dark.shape
visited = np.zeros_like(dark, dtype=bool)
res = []
for y in range(h):
    for x in range(w):
        if dark[y, x] and not visited[y, x]:
            q = deque([(y, x)])
            visited[y, x] = True
            minx, maxx, miny, maxy, size = x, x, y, y, 0
            while q:
                cy, cx = q.popleft()
                size += 1
                minx = min(minx, cx); maxx = max(maxx, cx)
                miny = min(miny, cy); maxy = max(maxy, cy)
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = cy+dy, cx+dx
                        if 0 <= ny < h and 0 <= nx < w and dark[ny, nx] and not visited[ny, nx]:
                            visited[ny, nx] = True
                            q.append((ny, nx))
            if size >= 250:
                res.append((size, minx, miny, maxx, maxy))
res.sort(reverse=True)
for r in res[:40]:
    print('size=%d x:%d-%d y:%d-%d' % r)
